// Cost control: perStar=4 gives about 120 reviews through the whole pipeline (roughly $0.30 of Claude credit).
// perStar=40 gives 1,200 reviews (roughly $3). Check your credit before raising it.
const langs = ['en', 'de', 'es', 'fr', 'ja', 'zh'];
const startedAt = Date.now();
return langs.map(lang => ({
  json: { lang, split: 'test', perStar: 4, seed: 42, batchSize: 8, model: 'claude-haiku-4-5',
          startDate: '2026-07-06', startedAt },
}));

// One HTTP response per language (same order as the Languages node).
const cfg = $('Config').all();
const stamp = new Date().toISOString();
const out = [];

// Seeded PRNG (mulberry32) so the stratified sample is reproducible.
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

$input.all().forEach((item, i) => {
  const { lang, perStar, seed } = cfg[i].json;
  const rows = String(item.json.data).split('\n').filter(l => l.trim()).map(l => JSON.parse(l));

  // The source files are sorted by star rating, so sample each rating separately.
  const byLabel = {};
  for (const r of rows) (byLabel[r.label] = byLabel[r.label] || []).push(r);

  const rand = rng(seed);
  for (const label of Object.keys(byLabel).sort()) {
    const g = byLabel[label];
    for (let k = g.length - 1; k > 0; k--) {
      const j = Math.floor(rand() * (k + 1));
      [g[k], g[j]] = [g[j], g[k]];
    }
    for (const r of g.slice(0, perStar)) {
      const text = String(r.text || '').trim();
      if (!text) continue;
      out.push({
        json: {
          review_id: `marc-${r.id}`,
          source: 'marc',
          product_category: null,
          rating: Number(label) + 1,
          review_text: text,
          detected_language: lang,
          translated_text: null,
          review_date: null,
          ingested_at: stamp,
        },
      });
    }
  }
});

return out;

// MARC has no review dates, so give each review a simulated posting date in a 12-week window
// (reproducible: same seed, same dates). Real platforms would supply the true date here.
const cfg = $('Config').first().json;
let a = (cfg.seed + 7) >>> 0;
const rand = () => {
  a = (a + 0x6D2B79F5) >>> 0;
  let t = a;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const start = new Date(cfg.startDate + 'T00:00:00Z').getTime();
return $input.all().map(i => {
  const week = Math.floor(rand() * 12);
  const day = Math.floor(rand() * 7);
  return { json: { ...i.json, review_date: new Date(start + (week * 7 + day) * 86400000).toISOString().slice(0, 10), sim_week: week } };
});

return $input.all().map(i => ({
  json: {
    ...i.json,
    translated_text: i.json.review_text,
    translation_language: 'en',
    translation_status: 'not_needed',
    translation_error: null,
    translation_prompt: null,
    translation_model: null,
  },
}));

const SYSTEM = "You are a professional translator for customer product reviews.\n\nFor every review you receive, do two things:\n1. Detect the language of the review and give its ISO 639-1 code (for example \"en\", \"de\", \"es\", \"fr\", \"ja\", \"zh\").\n2. Translate the review into natural, fluent English.\n\nRules:\n- Preserve the reviewer's sentiment, tone, and level of emphasis. Do not soften complaints or exaggerate praise.\n- Keep product names, brand names, numbers, prices, and emoji exactly as written.\n- Do not summarise, explain, or add anything that is not in the original.\n- If a review is already in English, return it unchanged.\n\nInput is a JSON array of objects with \"id\" and \"text\". Respond with JSON only, in exactly this shape and with one entry per input review, using the same ids:\n{\"translations\":[{\"id\":\"<id>\",\"language\":\"<iso code>\",\"english\":\"<translation>\"}]}";
const cfg = $('Config').first().json;
const reviews = $input.all().map(i => i.json);
const out = [];
for (let i = 0; i < reviews.length; i += cfg.batchSize) {
  const batch = reviews.slice(i, i + cfg.batchSize);
  const payload = batch.map(r => ({ id: r.review_id, text: r.review_text }));
  out.push({
    json: {
      batch_no: out.length + 1,
      reviews: batch,
      request: {
        model: cfg.model,
        max_tokens: 4000,
        system: SYSTEM,
        messages: [{ role: 'user', content: JSON.stringify(payload) }],
      },
    },
  });
}
return out;

const batches = $('Make batches').all();
const out = [];
$input.all().forEach((item, i) => {
  const b = batches[i].json;
  const map = {};
  let err = null;
  try {
    if (item.json.error) throw new Error(JSON.stringify(item.json.error).slice(0, 200));
    const raw = item.json.content[0].text.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
    for (const t of JSON.parse(raw).translations) map[t.id] = t;
  } catch (e) {
    err = String((e && e.message) || e).slice(0, 200);
  }
  for (const r of b.reviews) {
    const t = map[r.review_id];
    out.push({
      json: {
        ...r,
        translated_text: t ? t.english : null,
        translation_language: t ? t.language : null,
        translation_status: t ? 'ok' : 'failed',
        translation_error: t ? null : (err || 'missing from response'),
        translation_prompt: 'translate_v1',
        translation_model: b.request.model,
      },
    });
  }
});
return out;

const SYSTEM = "You are a customer-experience analyst who classifies product and service reviews written in any language.\n\nFor every review you receive, return:\n1. \"sentiment\": the reviewer's overall verdict on the product or service, one of:\n   - \"positive\": overall satisfied. Minor caveats do not change this: \"good but not perfect\", \"works well, a bit pricey\", \"does what I need, wish it were stronger\" are all positive.\n   - \"neutral\": genuinely torn or lukewarm. Significant good points and significant bad points of similar weight, or \"okay\", \"average\", \"does the job, nothing special\", with no clear lean toward recommending or regretting.\n   - \"negative\": the main message is disappointment or a real problem (defect, not as described, does not work, would not buy again or recommend). Praise for looks or side points does not outweigh it.\n2. \"topic\": the single main subject of the review, one of:\n   - \"shipping\": delivery speed, packaging, damaged or missing items, wrong item sent\n   - \"quality\": build quality, durability, defects, how well it works\n   - \"support\": customer service, returns, refunds, seller communication\n   - \"features\": missing or unwanted functionality, fit, compatibility, size, design\n   - \"price\": value for money, price changes, cost\n   - \"ux\": ease of use, setup, instructions, interface, software or app experience\n   - \"other\": anything that does not fit above\n3. \"confidence\": a number from 0 to 1 for how sure you are of the sentiment.\n4. \"stars\": the star rating (integer 1 to 5) you estimate this reviewer gave. 1 = terrible, 2 = poor, 3 = mixed or average, 4 = good, 5 = excellent.\n\nJudge the text itself, not any rating. Sarcasm counts as its true meaning. Do not translate; classify in the original language.\n\nInput is a JSON array of objects with \"id\" and \"text\". Respond with JSON only, in exactly this shape and with one entry per input review, using the same ids:\n{\"classifications\":[{\"id\":\"<id>\",\"sentiment\":\"positive|neutral|negative\",\"topic\":\"<topic>\",\"confidence\":<number>,\"stars\":<1-5>}]}";
const cfg = $('Config').first().json;
const reviews = $input.all().map(i => i.json);
const out = [];
for (let i = 0; i < reviews.length; i += 10) {
  const batch = reviews.slice(i, i + 10);
  const payload = batch.map(r => ({ id: r.review_id, text: r.review_text.slice(0, 1500) }));
  out.push({
    json: {
      batch_no: out.length + 1,
      reviews: batch,
      request: {
        model: cfg.model,
        max_tokens: 2000,
        system: SYSTEM,
        messages: [{ role: 'user', content: JSON.stringify(payload) }],
      },
    },
  });
}
return out;

const TOPICS = ['shipping', 'quality', 'support', 'features', 'price', 'ux', 'other'];
const batches = $('Make classify batches').all();
const label = s => {
  const n = Math.round(Math.min(Math.max(Number(s), 1), 5));
  return n <= 2 ? 'negative' : n === 3 ? 'neutral' : 'positive';
};
const out = [];
$input.all().forEach((item, i) => {
  const b = batches[i].json;
  const map = {};
  let err = null;
  try {
    if (item.json.error) throw new Error(JSON.stringify(item.json.error).slice(0, 200));
    const raw = item.json.content[0].text.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
    for (const c of JSON.parse(raw).classifications) map[c.id] = c;
  } catch (e) {
    err = String((e && e.message) || e).slice(0, 200);
  }
  for (const r of b.reviews) {
    const c = map[r.review_id];
    out.push({
      json: {
        ...r,
        sentiment: c ? label(c.stars) : null,
        stars_estimate: c ? Number(c.stars) : null,
        model_label: c ? c.sentiment : null,
        topic: c ? (TOPICS.includes(c.topic) ? c.topic : 'other') : null,
        confidence: c ? c.confidence : null,
        classify_status: c ? 'ok' : 'failed',
        classify_error: c ? null : (err || 'missing from response'),
      },
    });
  }
});
return out;

return $input.all().map(i => ({
