const TAXONOMY = {"0": "Damaged packaging and product during shipping", "1": "Poor overall quality and durability", "2": "Product fails or breaks shortly after purchase", "3": "Product does not work as advertised", "4": "Poor content quality and printing errors", "5": "Defective or malfunctioning components", "6": "Delayed or missing shipments and poor support", "7": "Wrong item received or non-functional product", "8": "Design flaws and uncomfortable fit", "9": "Connectivity and performance issues", "10": "Overpriced and rapid price drops", "11": "Missing parts and assembly defects", "12": "Wrong size sent or undersized product"};
const batches = $('Make cluster batches').all();
const out = [];
$input.all().forEach((item, i) => {
  const b = batches[i].json;
  const map = {};
  let err = null;
  try {
    if (item.json.error) throw new Error(JSON.stringify(item.json.error).slice(0, 200));
    const raw = item.json.content[0].text.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
