const NAMES = {"en": ["Emma", "Daniel", "Priya", "Marcus"], "de": ["Anna", "Lukas", "Sabine", "Jonas"], "es": ["Lucia", "Carlos", "Marta", "Diego"], "fr": ["Camille", "Louis", "Claire", "Hugo"], "ja": ["田中", "佐藤", "鈴木", "伊藤"], "zh": ["王女士", "李先生", "张女士", "陈先生"]};
const cfg = $('Config').first().json;
const out = [];
$input.all().forEach((it, idx) => {
  const r = it.json;
  if (!r.sentiment) {
    out.push({ json: { ...r, request: null } });
    return;
  }
  const name = NAMES[r.detected_language][idx % 4];
  const payload = {
    review: r.review_text.slice(0, 1500), customer_name: name, sentiment: r.sentiment, topic: r.topic,
    issue: r.issue, playbook: PLAYBOOKS[r.sentiment + '/' + r.topic],
  };
  out.push({
    json: {
      ...r, customer_name: name,
      request: { model: cfg.model, max_tokens: 600, system: SYSTEM, messages: [{ role: 'user', content: JSON.stringify(payload) }] },
    },
  });
});
return out;

const reqs = $('Make reply requests').all();
const model = $('Config').first().json.model;
const out = [];
$input.all().forEach((item, i) => {
  const r = reqs[i].json;
  let reply = null, err = null;
  try {
    if (item.json.error) throw new Error(JSON.stringify(item.json.error).slice(0, 200));
    const raw = item.json.content[0].text.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
    reply = JSON.parse(raw).reply.trim();
  } catch (e) {
    err = String((e && e.message) || e).slice(0, 200);
  }
  const { request, ...rest } = r;
  out.push({
    json: {
      ...rest, reply,
      reply_status: reply ? (r.sentiment === 'negative' ? 'pending_human_review' : 'draft_ready') : 'draft_failed',
      reply_error: reply ? null : err,
      reply_prompt: 'response_v2', reply_model: model,
    },
  });
});
return out;

const rows = $input.all().map(i => i.json);
const cnt = k => {
  const o = {};
  for (const r of rows) { const v = r[k] === null || r[k] === undefined ? 'none' : r[k]; o[v] = (o[v] || 0) + 1; }
  return o;
};
const lab = s => (s <= 2 ? 'negative' : s === 3 ? 'neutral' : 'positive');
const scored = rows.filter(r => r.sentiment && r.rating);
const acc3 = scored.filter(r => lab(r.rating) === r.sentiment).length / Math.max(scored.length, 1);
const polar = scored.filter(r => r.rating !== 3);
const accBin = polar.filter(r => lab(r.rating) === r.sentiment).length / Math.max(polar.length, 1);

const usage = {};
let cost = 0;
for (const [stage, node] of [['translate', 'Claude translate'], ['classify', 'Claude classify'],
                             ['issue_category', 'Claude issue category'], ['draft_reply', 'Claude draft reply']]) {
  let tin = 0, tout = 0;
  try { for (const it of $(node).all()) { const u = it.json.usage || {}; tin += u.input_tokens || 0; tout += u.output_tokens || 0; } } catch (e) {}
  // Claude Haiku 4.5 list price: $1 / $5 per million input / output tokens.
  const c = tin / 1e6 * 1 + tout / 1e6 * 5;
  usage[stage] = { tokens_in: tin, tokens_out: tout, cost_usd: Number(c.toFixed(4)) };
  cost += c;
}
